 CREATE OR REPLACE FUNCTION public.medicalconsentformbs(i_intakenumber character varying)                                                                                                                                                                                                                                                                                                                             
  RETURNS TABLE(youthname character varying, youthid character varying, folderid character varying, dob character varying, race character varying, physician_name character varying, physician_phone character varying, physician_address character varying, policy_holder_name character varying, policyname character varying, health_insurance_company character varying, policy_expiration_date character varying)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                    
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                      
    BEGIN                                                                                                                                                                                                                                                                                                                                                                                                           
         RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                               
           (select                                                                                                                                                                                                                                                                                                                                                                                                  
           cast(p.firstname ||' '|| p.lastname as character varying) as youthname,                                                                                                                                                                                                                                                                                                                                  
           cast (p.cjamspid as character varying)as youthid,                                                                                                                                                                                                                                                                                                                                                        
           idas.intakenumber as folderid,                                                                                                                                                                                                                                                                                                                                                                           
       cast(to_char(p.dob,'MM/DD/YYYY') as character varying) as DOB,                                                                                                                                                                                                                                                                                                                                               
       (select distinct typedescription from racetype where racetypekey=p.racetypekey) as race,                                                                                                                                                                                                                                                                                                                     
       cast(ppi.name as character varying) as physician_name ,                                                                                                                                                                                                                                                                                                                                                      
       cast(ppi.phone as character varying) as physician_phone ,                                                                                                                                                                                                                                                                                                                                                    
       cast(ppi.address1||' '||ppi.address2||' '||ppi.city||' '||ppi.state as character varying) as physician_address ,                                                                                                                                                                                                                                                                                             
       cast(phi.policyholdername  as character varying) as policy_holder_name,                                                                                                                                                                                                                                                                                                                                      
       cast(phi.policyname as character varying) as policyname,                                                                                                                                                                                                                                                                                                                                                     
       cast(phi.medicalinsuranceprovider as character varying) as health_insurance_company,                                                                                                                                                                                                                                                                                                                         
       cast(phi.expirationdate as character varying) as policy_expiration_date                                                                                                                                                                                                                                                                                                                                      
        from                                                                                                                                                                                                                                                                                                                                                                                                        
        intakedastaging idas                                                                                                                                                                                                                                                                                                                                                                                        
            join person p on idas.focuspersonid=p.personid and p.activeflag=1                                                                                                                                                                                                                                                                                                                                       
           left join personphycisianinfo  ppi on p.personid=ppi.personid and ppi.activeflag=1                                                                                                                                                                                                                                                                                                                       
           left join personhealthinsurance phi on p.personid=phi.personid and phi.activeflag=1                                                                                                                                                                                                                                                                                                                      
        where  idas.intakenumber = i_intakenumber) ;                                                                                                                                                                                                                                                                                                                                                                
    end;                                                                                                                                                                                                                                                                                                                                                                                                            
   $function$                                                                                                                                                                                                                                                                                                                                                                                                         

